      "proposed_laureates": [
        "Christian J. Bordé",
        "David E. Pritchard",
        "Mark A. Kasevich"
      ],
      "assessment": {
        "nobel_worthiness": "Atom interferometry created a powerful new measurement technology for inertial sensing, gravimetry, and precision tests.",
        "attribution": "The listed researchers made complementary foundational conceptual and experimental contributions; Kasevich is especially central to landmark demonstrations.",
        "maturity": "The methods are thoroughly established and have produced precise measurements in many independent laboratories.",
        "uncertainties": [
          "The historical attribution spans a broad community, making a three-person allocation difficult."
        ]
      }
    },
    {
      "rank": 3,
      "ballot_id": "B040",
      "proposed_laureates": [
        "Eli Yablonovitch",
        "John D. Joannopoulos",
        "Sajeev John"
      ],
      "assessment": {
        "nobel_worthiness": "Photonic band gaps gave optics a durable conceptual and engineering framework for controlling spontaneous emission and light propagation.",
        "attribution": "John and Yablonovitch established the field-defining ideas and demonstrations, with Joannopoulos providing essential theoretical and design foundations.",
        "maturity": "Photonic-crystal effects are extensively reproduced and underpin a wide range of optical devices and experiments.",
        "uncertainties": [
          "The breadth of later device contributions complicates a sharply bounded attribution."
        ]
      }
    },
    {
      "rank": 4,
      "ballot_id": "B015",
      "proposed_laureates": [
        "Alfred Y. Cho",
        "Federico Capasso",
        "Jérôme Faist"
      ],
      "assessment": {
        "nobel_worthiness": "Quantum cascade lasers constitute a distinct semiconductor-laser principle with major impact in mid-infrared and terahertz spectroscopy.",
        "attribution": "Faist and Capasso were central to the cascade-laser invention and realization; Cho's semiconductor heterostructure work is foundational.",
        "maturity": "The technology is mature, widely deployed, and has enabled sensitive molecular and environmental measurements.",
        "uncertainties": [
          "The relative scope of credit between the enabling epitaxy and the specific laser invention requires careful historical review."
        ]
      }
    },
    {
      "rank": 5,
      "ballot_id": "B014",
      "proposed_laureates": [
        "Jian-Wei Pan"
      ],
      "assessment": {
        "nobel_worthiness": "Multiphoton entanglement and long-distance satellite links made quantum communication a compelling experimentally demonstrated capability.",
        "attribution": "Pan has been an unusually central leader in both multiphoton experiments and the satellite-scale program.",
        "maturity": "Entanglement distribution and quantum-key experiments have been demonstrated at large scale, though the ultimate infrastructure remains developing.",
        "uncertainties": [
          "A single-name attribution may underrepresent major collaborators and prior quantum-communication foundations."
        ]
      }
    },
    {
      "rank": 6,
      "ballot_id": "B038",
      "proposed_laureates": [
        "Fedor Jelezko",
        "Jörg Wrachtrup",
        "Mikhail D. Lukin"
      ],
      "assessment": {
        "nobel_worthiness": "Optically detected diamond spins established a versatile solid-state platform for quantum sensing and coherent quantum control.",
        "attribution": "Jelezko and Wrachtrup led pivotal experimental development; Lukin made influential contributions to the platform's quantum-information use.",
        "maturity": "Diamond-spin sensing is reproducible, highly sensitive, and used broadly from materials science to biological measurement.",
        "uncertainties": [
          "The contribution encompasses several related advances and a larger community than the proposed trio."
        ]
      }
    },
    {
      "rank": 7,
      "ballot_id": "B022",
      "proposed_laureates": [
        "Alexandre Blais",
        "Andreas Wallraff",
        "Robert J. Schoelkopf"
      ],
      "assessment": {
        "nobel_worthiness": "Circuit QED supplied precise, scalable control and measurement of artificial atoms and has enabled much of superconducting quantum-circuit physics.",
        "attribution": "Blais developed key theory, while Wallraff and Schoelkopf provided defining experimental demonstrations.",
        "maturity": "The architecture is repeatedly realized worldwide and has become a major quantum-information and quantum-optics platform.",
        "uncertainties": [
          "Steven M. Girvin's foundational theoretical role makes exclusion from a three-person award difficult."
        ]
      }
    },
    {
      "rank": 8,
      "ballot_id": "B016",
      "proposed_laureates": [
        "Chandrashekhar Joshi",
        "Toshiki Tajima",
        "Victor Malka"
      ],
      "assessment": {
        "nobel_worthiness": "Laser-plasma wakefield acceleration opened a radically compact route to accelerating charged particles with extreme gradients.",
        "attribution": "Tajima formulated the original proposal, with Joshi and Malka among the leading experimental developers.",
        "maturity": "The core effect is firmly established and beam quality has progressed greatly, but broad accelerator replacement remains incomplete.",
        "uncertainties": [
          "Practical reproducibility, beam stability, and mature user-facility impact remain less settled than for conventional accelerators."
        ]
      }
    }
  ]
